import numpy as np
DESCRIPTION="ReLU RNN, 16 units, 10 steps, no bias: h_t=relu(x_t*Wx+h_(t-1)@Wh), out=h10@Wo, decision=argmax (class c = position c+1); the map is homogeneous of degree 1, so only the shape of x matters. Step 1 is a rule: h1=relu(x1*Wx)=max(x1,0)*relu(Wx)+max(-x1,0)*relu(-Wx) - each unit is a one-sided detector of sign(x1) scaled by its input weight (variables p1,n1). The step-1 pre-activation span [Wx,relu(Wx)@Wh,relu(-Wx)@Wh] has rank 3, so h2 lives on cones inside a 3-dim subspace and 7 of its coordinates fix the whole state; h3 (span rank 5) needs 10. Those coordinates are the registered variables, the other units follow by fixed linear maps P2 (7x16), P3 (10x16) fitted on the reachable set. From step 4 the state fills all 16 dims, so h4..h10 are registered whole. Weights are integers: Wx/1e3, Wh/1e5, Wo/1e4 with |w|<0.5 in 1e-3 units."
WX=np.array([69,-10565,15,-123,10157,-281,-10996,-13169,-12312,-228,60,148,298,-47,-1321,-119])/1e3
WH=np.array([16086,-10829,-8354,-122938,3538,22449,-9288,-2142,-461,-3175,2329,9160,4806,15144,40284,26571,71088,40936,-10195,119525,3562,-51,-13511,-10036,63390,-35731,21934,24272,46917,22470,17081,65188,-17373,50370,96884,168,-49231,-3115,53496,67367,62536,424,4027,12053,-15611,38360,33529,38409,2122,1161,3909,-35856,-339,-20049,2726,-801,46,-4387,-7655,-7680,-31037,42706,-35769,37873,59488,87136,173072,34419,-98561,118705,-4709,131662,-4149,14581,175515,171479,127710,46402,87055,17943,-91342,11775,-1015,-51754,170,-42111,3827,231,-1696,4286,-1441,-7336,-13563,-8552,-42392,-66316,113276,99540,-10254,48519,9330,1522,36057,-18246,-29,-8919,-19325,-47305,-10376,12046,76509,38057,-77582,-104767,2269,-39920,-2937,-59334,-12608,7815,-109412,-503170,20954,38181,-5224,211,-71193,-16142,-79299,-12038,15453,-107414,-8156,-84976,-8202,16669,61539,-109154,-20933,-16269,-27942,-28892,-6498,-72353,-142374,-68628,-22885,20812,8339,29736,-64008,278,-6836,-55285,13674,67709,80975,3941,-64936,-19515,30745,2389,1522,21385,-654,12241,2804,-388,3809,3272,-92,432,-11956,27689,25044,-109297,15023,845,1762,-19371,-1221,32779,1892,2990,5489,5266,109639,19865,682,-8846,1724,127960,22485,4300,5533,49884,-5915,26139,3956,6951,4158,1644,-5294,66275,61168,-26148,-1888,-22410,7666,2953,4050,-25857,-2693,-905,1607,2172,66,-2579,7699,-37510,41392,-60501,-15920,-52917,42038,7915,2686,58845,-3263,20480,8612,-1,3189,10716,-14415,-9608,34130,-21998,35504,13763,834,2006,-4666,81045,-1095,7379,-789,-1253,-1337,-974,-1823,-11855,45148,65373,-19347,22866],float).reshape(16,16)/1e5
WO=np.array([19619,-26916,-16519,7727,6832,19625,12431,-29048,-295,6859,60943,25618,-16609,-58617,-48928,-12115,21677,44102,-14341,-474,-9189,-22234,-400,287,201,483,10833,152,5781,174,6677,16943,-5052,-5413,-473,-9149,16959,-5835,-6096,-5999,-150,424,5766,6661,7499,5672,461,414,498,-49917,-228,-82,-77,-347,-5099,-6402,-6782,-369,33976,-419,25277,47827,31923,-12173,-55540,-56349,-30802,9535,36236,-6710,-27823,483,46942,73282,58693,9214,-28488,-54078,-49967,-37894,-35740,-66982,-62053,-14946,31011,54853,43942,14365,36448,328,-20997,-10342,412,7472,15930,19542,436,217,-16593,-6037,163,-16662,-28081,-38699,16610,11078,20269,16418,7040,16744,10053,12669,5,295,-45582,-5,454,7857,181,7847,11856,17026,14175,236,321,-27947,-22195,252,-459,266,244,373,-22345,247,178,20864,-13886,227,73,260,-51440,6083,11130,13094,12288,-6229,-10064,12161,88,11820,10099,23006,26151,-11369,-9367,-7243,-9494,-8294,-9161,-8525],float).reshape(16,10)
WO=np.where(np.abs(WO)<500,WO/1e3,WO/1e4)
A=np.maximum(WX,0.);B=np.maximum(-WX,0.);C2=[0,1,2,4,10,13,14];C3=[0,1,2,3,4,5,6,8,10,13]
def S(h,y):return np.maximum(y*WX+h@WH,0.)
_r=np.random.RandomState(0).randn(2000,10)
h=S(np.maximum(_r[:,0:1]*WX,0.),_r[:,1:2]);P2=np.linalg.lstsq(h[:,C2],h,rcond=None)[0]
h=S(h,_r[:,2:3]);P3=np.linalg.lstsq(h[:,C3],h,rcond=None)[0]
def model(x,iv):
    x=np.asarray(x,float);p=iv('p1',np.maximum(x[:,0],0.));n=iv('n1',np.maximum(-x[:,0],0.))
    h=np.maximum(p[:,None]*A+n[:,None]*B,0.)
    for k,C,P in ((0,C2,P2),(1,C3,P3)):
        z=S(h,x[:,k+1:k+2]);v=iv('h%d'%(k+2),z[:,C]);h=z+(v-z[:,C])@P
    for t in range(3,10):h=iv('h%d'%(t+1),S(h,x[:,t:t+1]))
    return h@WO
ALIGN=dict([('p1',['h1']),('n1',['h1'])]+[('h%d'%t,['h%d'%t]) for t in range(2,11)])
